-- +goose Up
-- Passwords for WebDAV and other clients that can't do the browser login
-- (OIDC users have no account password at all). Generated by the server
-- and shown once.
CREATE TABLE app_passwords (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id      uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    name         text NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
    -- SHA-256 of the password. A fast hash is enough for ~125 random bits,
    -- and it has to be: clients send it with every request.
    token_hash   bytea NOT NULL UNIQUE CHECK (length(token_hash) = 32),
    created_at   timestamptz NOT NULL DEFAULT now(),
    last_used_at timestamptz
);

CREATE INDEX app_passwords_user ON app_passwords (user_id);

-- +goose Down
DROP TABLE app_passwords;
